// Nodo Code "Preparar correo" (Run Once for All Items).
// Limpia cada correo antes de pasarlo al modelo: descarta remitentes internos y automáticos,
// corta el hilo citado y reúne los emails que aparecen de verdad en el mensaje.

// Dominios de tu propia empresa: los correos internos se ignoran.
const DOMINIOS_PROPIOS = ['tuempresa.com'];
const REMITENTES_IGNORADOS = /^(no-?reply|noreply|mailer-daemon|postmaster|notificaciones|notifications?|bounce|newsletter)/i;
const REGEX_EMAIL = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;

const esPropio = (email) => DOMINIOS_PROPIOS.some((d) => email.endsWith('@' + d));
const direcciones = (campo) => ((campo && campo.value) || [])
  .map((v) => ({ email: String(v.address || '').toLowerCase().trim(), nombre: String(v.name || '').trim() }))
  .filter((v) => v.email);
const formatear = (lista) => lista.map((v) => (v.nombre ? v.nombre + ' <' + v.email + '>' : v.email)).join(', ');

const salida = [];
$input.all().forEach((item, indice) => {
  const m = item.json;
  const remitente = direcciones(m.from)[0] || { email: '', nombre: '' };
  if (!remitente.email || esPropio(remitente.email) || REMITENTES_IGNORADOS.test(remitente.email)) return;

  const para = direcciones(m.to);
  const copia = direcciones(m.cc);

  let texto = String(m.text || '');
  if (!texto && m.html) texto = String(m.html).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');

  // Marcas habituales de "aquí empieza el hilo citado" en español e inglés.
  const cortes = [
    /^\s*\**(De|From|Enviado el|Sent)\s*:\**\s/im,
    /^\s*El .{5,200}escribi[oó]:/im,
    /^\s*On .{5,200}wrote:/im,
    /^-{2,}\s*(Original Message|Mensaje original)/im,
    /^_{8,}/m
  ];
  let fin = texto.length;
  for (const r of cortes) {
    const pos = texto.search(r);
    if (pos > 0 && pos < fin) fin = pos;
  }
  const mensajeNuevo = texto.slice(0, fin).replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);

  // Solo se podrá crear en el CRM a personas cuyo email esté en esta lista.
  const candidatos = [];
  const anadir = (email) => {
    if (email && !esPropio(email) && email !== remitente.email && !candidatos.includes(email)) candidatos.push(email);
  };
  para.concat(copia).forEach((v) => anadir(v.email));
  (mensajeNuevo.match(REGEX_EMAIL) || []).forEach((e) => anadir(e.toLowerCase()));
  const esRespuesta = /^\s*(re|rv|fw|fwd|reenv)\s*:/i.test(String(m.subject || '')) || fin < texto.length;

  const textoParaIA = [
    'Remitente: ' + formatear([remitente]),
    'Para: ' + formatear(para),
    'CC: ' + (formatear(copia) || '(nadie)'),
    'Asunto: ' + (m.subject || ''),
    'Fecha: ' + (m.date || ''),
    'Es respuesta a un hilo previo: ' + (esRespuesta ? 'sí' : 'no'),
    '',
    'Mensaje nuevo (sin el hilo citado):',
    mensajeNuevo || '(vacío)'
  ].join('\n');

  salida.push({
    json: {
      gmailId: m.id || '',
      threadId: m.threadId || '',
      asunto: m.subject || '',
      fecha: m.date || '',
      remitenteEmail: remitente.email,
      remitenteNombre: remitente.nombre,
      candidatos: candidatos,
      esRespuesta: esRespuesta,
      mensajeNuevo: mensajeNuevo,
      textoParaIA: textoParaIA
    },
    pairedItem: { item: indice }
  });
});
return salida;

// Nodo Code "Validar datos del contacto" (Run Once for All Items).
// El modelo propone; este nodo decide. Nada llega al CRM sin pasar por aquí:
//  - solo se aceptan emails que aparecen literalmente en el correo (lista "candidatos"),
//  - la industria tiene que ser un valor permitido,
//  - los teléfonos se normalizan,
//  - si el remitente ya existe en el CRM, no se crea de nuevo.

// Valores permitidos de la propiedad "industry" en tu CRM.
const INDUSTRIAS = ['Alimentación', 'Educación', 'Minería', 'Hostelería', 'Oficinas', 'Industria', 'Salud', 'Otro'];
const DOMINIOS_GENERICOS = ['gmail.com', 'hotmail.com', 'outlook.com', 'yahoo.com', 'yahoo.es', 'live.com', 'icloud.com', 'hotmail.es', 'outlook.es', 'msn.com'];
const REGEX_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const limpiar = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const titulo = (v) => limpiar(v).toLowerCase().replace(/(^|[\s'-])(\p{L})/gu, (a, sep, letra) => sep + letra.toUpperCase());

// Normalización pensada para Chile (+56). Adáptala al país de tus contactos.
const normalizarTelefono = (v) => {
  const bruto = limpiar(v);
  if (!bruto) return '';
  const digitos = bruto.replace(/\D/g, '');
  if (digitos.length < 8) return '';
  if (bruto.startsWith('+')) return '+' + digitos;
  if (digitos.length === 9 && digitos.startsWith('9')) return '+56' + digitos;
  if (digitos.length === 11 && digitos.startsWith('56')) return '+' + digitos;
  return bruto;
};
const industriaValida = (v) => (INDUSTRIAS.includes(limpiar(v)) ? limpiar(v) : '');
const sinVacios = (o) => { Object.keys(o).forEach((k) => { if (!o[k]) delete o[k]; }); return o; };

const salida = [];
$input.all().forEach((item, i) => {
  const r = item.json.output || {};
  const tipo = limpiar(r.tipo) || 'otro';
  if (tipo !== 'derivacion' && tipo !== 'solicitud_directa') return;

  const correo = $('Preparar correo').itemMatching(i).json;
  const busqueda = $('Buscar remitente en HubSpot').itemMatching(i).json || {};
  const remitenteCrm = ((busqueda.results || [])[0] || {}).properties || {};
  const remitenteExiste = Number(busqueda.total || 0) > 0;
  const dominioRemitente = correo.remitenteEmail.split('@')[1] || '';
  const derivadoPor = correo.remitenteNombre ? correo.remitenteNombre + ' <' + correo.remitenteEmail + '>' : correo.remitenteEmail;

  if (tipo === 'solicitud_directa') {
    if (remitenteExiste) return;
    const s = r.remitente || {};
    let nombre = titulo(s.nombre);
    let apellido = titulo(s.apellido);
    if (!nombre && correo.remitenteNombre && !correo.remitenteNombre.includes('@')) {
      const partes = titulo(correo.remitenteNombre).split(' ');
      nombre = partes.shift() || '';
      apellido = apellido || partes.join(' ');
    }
    const propiedades = sinVacios({
      email: correo.remitenteEmail,
      firstname: nombre,
      lastname: apellido,
      jobtitle: limpiar(s.cargo),
      company: limpiar(s.empresa),
      industry: industriaValida(s.industria),
      phone: normalizarTelefono(s.telefono)
    });
    propiedades.hs_analytics_source = 'DIRECT_TRAFFIC';
    salida.push({
      json: { tipo: tipo, propiedades: propiedades, derivadoPor: '', motivo: limpiar(r.motivo), asunto: correo.asunto, gmailId: correo.gmailId },
      pairedItem: { item: i }
    });
    return;
  }

  const vistos = [];
  for (const c of (Array.isArray(r.contactos) ? r.contactos : [])) {
    const email = limpiar(c.email).toLowerCase();
    if (!REGEX_EMAIL.test(email)) continue;
    if (!correo.candidatos.includes(email)) continue; // el modelo no puede inventar destinatarios
    if (vistos.includes(email)) continue;
    vistos.push(email);

    // Si la persona derivada es de la misma empresa que el remitente, hereda empresa e industria del CRM.
    const dominio = email.split('@')[1];
    const mismaEmpresa = dominio === dominioRemitente && !DOMINIOS_GENERICOS.includes(dominio);

    let industria = '';
    if (mismaEmpresa && INDUSTRIAS.includes(remitenteCrm.industry)) industria = remitenteCrm.industry;
    else industria = industriaValida(c.industria);

    let empresa = limpiar(c.empresa);
    if (mismaEmpresa && remitenteCrm.company) empresa = limpiar(remitenteCrm.company);

    const propiedades = sinVacios({
      email: email,
      firstname: titulo(c.nombre),
      lastname: titulo(c.apellido),
      jobtitle: limpiar(c.cargo),
      company: empresa,
      industry: industria,
      phone: normalizarTelefono(c.telefono)
    });
    propiedades.hs_analytics_source = 'REFERRALS';

    salida.push({
      json: { tipo: tipo, propiedades: propiedades, derivadoPor: derivadoPor, motivo: limpiar(r.motivo), asunto: correo.asunto, gmailId: correo.gmailId },
      pairedItem: { item: i }
    });
  }
});
return salida;

// Nodo Code "Comprobar resultado" (Run Once for All Items).
// Resume qué pasó con cada contacto y hace fallar la ejecución si el CRM rechazó alguno,
// para que el error no pase inadvertido. Un 409 (ya existía) no es un error.

const resultados = $input.all().map((item, i) => {
  const origen = $('Validar datos del contacto').itemMatching(i).json;
  const codigo = Number(item.json.statusCode || 0);
  const cuerpo = item.json.body || {};
  let estado = 'error';
  if (codigo === 201 || codigo === 200) estado = 'creado';
  else if (codigo === 409) estado = 'ya existía';
  return {
    json: {
      tipo: origen.tipo || '',
      estado: estado,
      email: origen.propiedades.email,
      hubspotId: cuerpo.id || '',
      derivadoPor: origen.derivadoPor,
      asunto: origen.asunto,
      detalle: estado === 'error' ? (cuerpo.message || JSON.stringify(cuerpo).slice(0, 300)) : ''
    },
    pairedItem: { item: i }
  };
});
const fallos = resultados.filter((r) => r.json.estado === 'error');
if (fallos.length > 0) {
  throw new Error('HubSpot rechazó ' + fallos.length + ' contacto(s): ' + fallos.map((f) => f.json.email + ' → ' + f.json.detalle).join(' | '));
}
return resultados;
